To reliably determine if a browser supports mouse-over events, you can use the approach you've outlined while making a few enhancements for clarity and correctness. The key is to listen for a `mousemove` event as your indicator of mouse support, and use `touchstart` to identify touch devices. If both events fire in your browser, you can confidently determine that it supports mouse events.

Here's a simplified and improved version of your code snippet:

```javascript
jQuery(function() {
    // Variable to hold whether the device has a mouse
    let hasMouse = false;

    // Detect mouse support
    jQuery("body").one("mousemove", function(e) {
        hasMouse = true;
        attachMouseEvents(); // Call the function that defines mouse event behavior
    });

    // Detect touch support
    jQuery("body").one("touchstart", function(e) {
        if (!hasMouse) {
            // If touchstart fires first and we haven't detected mouse movement,
            // it indicates that this is a touch device, so we will not attach mouse events
            attachTouchEvents(); // Call the function that defines touch event behavior
        } else {
            // Unbind mouse detection as it was identified
            jQuery("body").off("mousemove");
        }
    });
});

function attachMouseEvents() {
