    ID      bson.ObjectId `bson:"_id"`
    Name    string        `bson:"name"`
    Country string        `bson:"country"`
}
```

### Step 2: Create the Index

Make sure you have the necessary index created in your MongoDB collection:

```javascript
db.users.createIndex({ country: 1, name: 1, _id: 1 });
```

### Step 3: Implementing Efficient Pagination

To achieve pagination without using `Skip`, follow these steps:

1. For the first page, fetch the results normally.
2. For subsequent pages, keep passing the last seen user’s `Name` and `ID` to construct your query.

Here’s a Go code snippet to demonstrate the approach:

```go
package main

import (
	"fmt"
	"gopkg.in/mgo.v2"
	"gopkg.in/mgo.v2/bson"
)

type User struct {
	ID      bson.ObjectId `bson:"_id"`
	Name    string        `bson:"name"`
	Country string        `bson:"country"`
}

// Function for fetching paginated results
func getPaginatedUsers(session *mgo.Session, country string, lastSeen *User, limit int) ([]*User, error) {
	c := session.DB("your_database").C("users")
	var users []*User

	// Build the query
	query := c.Find(bson.M{"country": country})

	// Apply range query if lastSeen is not nil
	if lastSeen != nil {
		query = query.Find(bson.M{
			"$or": []bson.M{
				{"name": bson.M{"$gt": lastSeen.Name}},
				{"name": lastSeen.Name, "_id": bson.M{"$gt": lastSeen.ID}},
			},
		})
	}

	// Sort the results
	query = query.Sort("name", "_id").Limit(limit)

	// Fetch results
	err := query.All(&users)
	if err != nil {
		return nil, err
	}

	return users, nil
}

func main() {
	// Connect to MongoDB
	session, err := mgo.Dial("your_mongo_url")
	if err != nil {
		panic(err)
	}
	defer session.Close()

	// Fetch the first page
	var lastSeen *User
	limit := 10

	// Example: Paginate through users from the USA
	for page := 1; page <= 5; page++ { // Let's say you want to fetch 5 pages
		users, err := getPaginatedUsers(session, "USA", lastSeen, limit)
		if err != nil {
			fmt.Println("Error fetching paginated users:", err)
			break
		}

		if len(users) == 0 {
			fmt.Println("No more users found.")
			break
		}

		// Print the users for the current page
		for _, user := range users {
			fmt.Printf("User: %s, ID: %s\n", user.Name, user.ID.Hex())
		}

		// Set lastSeen for next iteration
		lastSeen = users[len(users)-1] // Get the last user from the current page
	}
}
```

### Explanation:

1. **Pagination Logic**: This function takes the last seen user as an argument. For the first request, you can pass `nil` for `lastSeen`. Each subsequent request uses the last user from the previous result set to filter results efficiently.

2. **Query Construction**: The query filters users based on the country and the last seen user's name and ID, efficiently allowing MongoDB to use its index optimally.

3. **Sorting**: The sorting is done in a way that ensures the results are sorted by name, then by `_id`, which helps MongoDB make efficient use of the index.

By implementing this logic, you effectively mitigate the performance issues associated with using `Skip` for larger pages.

