Here’s an updated version of your `scoreQuiz` function that demonstrates this idea:

```javascript
function scoreQuiz(allCorrectAnswers, selections) {
  let totalScore = 0;

  // Check if the input arrays are the same length
  if (allCorrectAnswers.length === selections.length) {
    // Create frequency maps for correct answers and selections
    const answerCount = {};
    const selectionCount = {};

    allCorrectAnswers.forEach(answer => {
      answerCount[answer] = (answerCount[answer] || 0) + 1; // Count occurrences of each answer
    });

    selections.forEach(selection => {
      selectionCount[selection] = (selectionCount[selection] || 0) + 1; // Count occurrences of each selection
    });

    // Compare frequency maps to calculate totalScore
    for (let answer in answerCount) {
