Here’s how you can modify your code to support both mobile and desktop interactions:

```javascript
const myObject = document.getElementById("scroll-window");
play3D();
let a = 0;
let b = 0;

const handlePointerDown = (e) => {
    a = e instanceof TouchEvent ? e.touches[0].clientX : e.clientX;
    myObject.addEventListener('pointermove', handlePointerMove);
    myObject.addEventListener('touchmove', handlePointerMove);
};

const handlePointerMove = (e) => {
    const clientX = e instanceof TouchEvent ? e.touches[0].clientX : e.clientX;
    b = clientX;

    let motionx = e.movementX || 0; // movementX is not available in touch events

