    });

    $(".load-fragment").click(function(event) {
        event.preventDefault(); // Prevent default link behavior
        var $thiz = $(this); // Making the current object
        var fname = $thiz.attr("href"); // Getting the href of the clicked element
        var dynDivID = "divContent" + $thiz.attr("id"); // Name of the dynamic div ID
