               Mvx.IoCProvider.RegisterSingleton(() => new PushNotificationData(pushData));
           }
       }

       return true;
   }
   ```

   **Android:**
   In your `MainActivity.cs`, you can handle the intent data:

   ```csharp
   protected override void OnCreate(Bundle savedInstanceState)
   {
       base.OnCreate(savedInstanceState);

       // other initialization code...

       var intent = Intent;
       if (intent.Extras != null && intent.HasExtra("push_notification"))
       {
           var pushData = intent.GetStringExtra("push_notification");
           Mvx.IoCProvider.RegisterSingleton(() => new PushNotificationData(pushData));
       }
   }
   ```

2. **Create a Push Notification Data Model**

   Define a simple model to package the push notification data:

   ```csharp
   public class PushNotificationData
   {
       public string Message { get; set; }

       public PushNotificationData(string json)
       {
           // Parse your json data to retrieve the message
           Message = json; // Replace this with actual parsing logic.
       }
   }
   ```

3. **Modify Your Custom AppStart Class**

   Update your custom AppStart class to handle this push notification data:

   ```csharp
   protected override Task NavigateToFirstViewModel(object hint)
   {
       // Check for the registered push notification data
       var pushData = Mvx.IoCProvider.Resolve<PushNotificationData>();

       if (pushData != null && !string.IsNullOrEmpty(pushData.Message))
       {
           NavigationService.Navigate<AppSyncViewModel, string>(pushData.Message);
       }
       else
       {
           NavigationService.Navigate<AppSyncViewModel, object>(hint);
       }

       return Task.CompletedTask;
   }
   ```

4. **Handle the Input in Your ViewModel**

   In your `AppSyncViewModel`, handle the received parameter accordingly:

   ```csharp
   public void Prepare(string parameter)
   {
       if (!string.IsNullOrEmpty(parameter))
       {
           _comeFromPushNotification = true;
           Console.WriteLine($"Received push notification: {parameter}");
       }
       else
       {
           _comeFromPushNotification = false;
       }
   }
   ```

5. **Usage in ViewModel Initialization**

   Implement any logic in your `Initialize` method based on the `_comeFromPushNotification` flag:

   ```csharp
   public override async Task Initialize()
   {
       await base.Initialize();

       if (_comeFromPushNotification)
       {
