2. **Remove `setTargetFragment(this, 1)`** and instead invoke method directly:
   ```kotlin
   class CourseTypeListDialogFragment: DaggerAppCompatDialogFragment() {
       private lateinit var listener: ApplySelectedCourseTypeFilter

       override fun onAttach(context: Context) {
           super.onAttach(context)
           listener = context as ApplySelectedCourseTypeFilter
       }

       // Assuming you have a method that gets called on an action
       fun onTypeSelected(selectedType: String) {
           listener.applySelectedCourseType(selectedType)
           dismiss()
       }
   }
